64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
75	     * {@code customerCode}, {@code registrationDate} and {@code membershipLevel} is emitted to the
76	     * logger named {@code AUDIT}.
77	     */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    /**
81	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
82	     * at least one dot and no whitespace on either side.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
86	
87	    /**
88	     * Common street-type abbreviations expanded during address normalization. Keys are the
89	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
90	     * expanded form.
91	     */
92	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
93	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
94	
95	    /**
96	     * Required national-number length per E.164 country code (the digits that follow the country
97	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
98	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
99	     */
100	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
101	        Map.of("1", 10, "61", 9);
102	
103	    /**
104	     * The maximum number of owners a single city may contain. A create request for a city that
105	     * already holds this many owners is rejected with a 409 response.
106	     */
107	    private static final int MAX_OWNERS_PER_CITY = 50;
108	
109	    /**
110	     * The maximum number of owners that may be registered in a single day. A create request made
111	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
112	     * response.
113	     */
114	    private static final int MAX_OWNERS_PER_DAY = 100;
115	
116	    /**
117	     * The number of owners that must already carry a day's {@code registrationDate} before a create
118	     * for that day is flagged as a bulk signup. Once more than this many owners already exist for the
119	     * day, the new owner is created with {@code bulkSignupWarning} set to {@code true}.
120	     */
121	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
122	
123	    private final ClinicService clinicService;
124	
125	    private final OwnerMapper ownerMapper;
126	
127	    private final PetMapper petMapper;
128	
129	    private final VisitMapper visitMapper;
130	
131	    public OwnerRestControllerV1(ClinicService clinicService,
132	                                 OwnerMapper ownerMapper,
133	                                 PetMapper petMapper,
134	                                 VisitMapper visitMapper) {
135	        this.clinicService = clinicService;
136	        this.ownerMapper = ownerMapper;
137	        this.petMapper = petMapper;
138	        this.visitMapper = visitMapper;
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
169	        normalizeAddress(ownerFieldsDto);
170	        validateRequiredFields(ownerFieldsDto);
171	        normalizeTelephone(ownerFieldsDto);
172	        rejectDuplicateTelephone(ownerFieldsDto);
173	        rejectDuplicateHousehold(ownerFieldsDto);
174	        rejectCityAtCapacity(ownerFieldsDto);
175	        resolveRegistrationDate(ownerFieldsDto);
176	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
177	        normalizeEmail(ownerFieldsDto);
178	        rejectDuplicateEmail(ownerFieldsDto);
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        assignCustomerCode(owner);
182	        assignMembershipNumber(owner);
183	        assignNamesakeCount(owner);
184	        assignMembershipLevel(owner);
185	        assignBulkSignupWarning(owner);
186	        assignHousehold(owner, ownerFieldsDto);
187	        assignHouseholdMembership(owner);
188	        this.clinicService.saveOwner(owner);
189	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
190	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
191	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner == null) {
202	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	        }
204	        currentOwner.setAddress(ownerFieldsDto.getAddress());
205	        currentOwner.setCity(ownerFieldsDto.getCity());
206	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
207	        currentOwner.setLastName(ownerFieldsDto.getLastName());
208	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
209	        normalizeEmail(ownerFieldsDto);
210	        currentOwner.setEmail(ownerFieldsDto.getEmail());
211	        this.clinicService.saveOwner(currentOwner);
212	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Transactional
217	    @Override
218	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        this.clinicService.deleteOwner(owner);
224	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
230	        Owner owner = this.clinicService.findOwnerById(ownerId);
231	        if (owner == null) {
