292	    /**
293	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
294	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
295	     * does not catch). The names of all offending fields are collected so the caller receives a
296	     * 400 response whose {@code errors} array lists each one.
297	     */
298	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
299	        List<String> missingFields = new ArrayList<>();
300	        if (isBlank(ownerFieldsDto.getFirstName())) {
301	            missingFields.add("firstName");
302	        }
303	        if (isBlank(ownerFieldsDto.getLastName())) {
304	            missingFields.add("lastName");
305	        }
306	        if (isBlank(ownerFieldsDto.getAddress())) {
307	            missingFields.add("address");
308	        }
309	        if (isBlank(ownerFieldsDto.getCity())) {
310	            missingFields.add("city");
311	        }
312	        if (isBlank(ownerFieldsDto.getTelephone())) {
313	            missingFields.add("telephone");
314	        }
315	        if (!missingFields.isEmpty()) {
316	            throw new InvalidOwnerFieldsException(missingFields);
317	        }
318	    }
319	
320	    private static boolean isBlank(String value) {
321	        return value == null || value.trim().isEmpty();
322	    }
323	
324	    /**
325	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
326	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
327	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
328	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
329	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
330	     * means an address that is blank after normalization is rejected like a missing one.
331	     */
332	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
333	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
334	    }
335	
336	    /**
337	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
338	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
339	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
340	     * address is returned unchanged, making it safe to apply to stored values during comparison.
341	     */
342	    private static String canonicalAddress(String address) {
343	        if (address == null) {
344	            return null;
345	        }
346	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
347	        if (collapsed.isEmpty()) {
348	            return "";
349	        }
350	        String[] tokens = collapsed.split(" ");
351	        StringBuilder sb = new StringBuilder(collapsed.length());
352	        for (int i = 0; i < tokens.length; i++) {
353	            if (i > 0) {
354	                sb.append(' ');
355	            }
356	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
357	        }
358	        return sb.toString();
359	    }
360	
361	    /**
362	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
363	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
364	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
365	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
366	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
367	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
368	     * written back onto the request so it is what gets stored and returned. Any value that cannot
369	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
370	     * {@code telephone}.
371	     */
372	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
373	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
374	    }
375	
376	    /**
377	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
378	     * (400) naming {@code telephone} when it cannot form a valid number.
379	     */
380	    private static String toE164(String telephone) {
381	        if (telephone == null) {
382	            throw new InvalidOwnerFieldsException(List.of("telephone"));
383	        }
384	        boolean hasCountryCode = telephone.trim().startsWith("+");
385	        String digits = telephone.replaceAll("\\D", "");
386	        String countryCode;
387	        String national;
388	        if (hasCountryCode) {
389	            countryCode = matchCountryCode(digits);
390	            national = digits;
391	        } else {
392	            countryCode = "61";
393	            if (digits.startsWith("0")) {
394	                digits = digits.substring(1);
395	            }
396	            national = "61" + digits;
397	        }
398	        if (!national.matches("[0-9]{8,15}")) {
399	            throw new InvalidOwnerFieldsException(List.of("telephone"));
400	        }
401	        if (countryCode != null) {
402	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
403	            if (requiredLength != null
404	                && national.length() - countryCode.length() != requiredLength) {
405	                throw new InvalidOwnerFieldsException(List.of("telephone"));
406	            }
407	        }
408	        return "+" + national;
409	    }
410	
411	    /**
412	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
413	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
414	     * the number is not length-checked against a country.
415	     */
416	    private static String matchCountryCode(String digits) {
417	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
418	            .filter(digits::startsWith)
419	            .max(Comparator.comparingInt(String::length))
420	            .orElse(null);
421	    }
422	
423	    /**
424	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
425	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
426	     * each existing owner's stored telephone is converted the same way before comparison so numbers
427	     * that only differ in formatting still collide. A match results in a 409 response naming
428	     * {@code telephone}.
429	     */
430	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
431	        String telephone = ownerFieldsDto.getTelephone();
432	        for (Owner existing : this.clinicService.findAllOwners()) {
433	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
434	                throw new DuplicateOwnerTelephoneException(telephone);
435	            }
436	        }
437	    }
438	
439	    /**
440	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
441	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
442	     */
443	    private static String normalizeExisting(String telephone) {
444	        try {
445	            return toE164(telephone);
446	        } catch (InvalidOwnerFieldsException ex) {
447	            return null;
448	        }
449	    }
450	
451	    /**
452	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
453	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
454	     * single space, so values that differ only in letter case or spacing still collide. When the
455	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
456	     * household members to share a name and address. A match results in a 409 response naming
457	     * {@code lastName} and {@code address}.
458	     */
459	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
460	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
461	            return;
462	        }
463	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
464	        String address = canonicalAddress(ownerFieldsDto.getAddress());
465	        for (Owner existing : this.clinicService.findAllOwners()) {
466	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
467	                && address.equals(canonicalAddress(existing.getAddress()))) {
468	                throw new DuplicateOwnerHouseholdException(
469	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
470	            }
471	        }
472	    }
473	
474	    /**
475	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
476	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
477	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
478	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
479	     */
480	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
481	        String city = ownerFieldsDto.getCity();
482	        int count = 0;
483	        for (Owner existing : this.clinicService.findAllOwners()) {
484	            if (city.equalsIgnoreCase(existing.getCity())) {
485	                count++;
486	            }
487	        }
488	        if (count >= MAX_OWNERS_PER_CITY) {
489	            throw new OwnerCityAtCapacityException(city);
490	        }
491	    }
492	
493	    /**
494	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
495	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
496	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
497	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
498	     */
499	    private void rejectDailyLimitReached(LocalDate registrationDate) {
500	        int count = 0;
501	        for (Owner existing : this.clinicService.findAllOwners()) {
502	            if (registrationDate.equals(existing.getRegistrationDate())) {
503	                count++;
504	            }
505	        }
506	        if (count >= MAX_OWNERS_PER_DAY) {
507	            throw new DailyOwnerLimitReachedException(registrationDate);
508	        }
509	    }
510	
511	    /**
512	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
513	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
514	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
515	     */
516	    private static String normalizeForComparison(String value) {
517	        if (value == null) {
518	            return "";
519	        }
520	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
521	    }
522	
523	    /**
524	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
525	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
526	     * written back onto the request so that is what gets stored and returned. A present but invalid
527	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
528	     */
529	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
530	        String email = ownerFieldsDto.getEmail();
531	        if (email == null) {
532	            return;
533	        }
534	        String trimmed = email.trim();
535	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
536	            throw new InvalidOwnerFieldsException(List.of("email"));
537	        }
538	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
539	    }
540	
541	    /**
542	     * Rejects creating an owner whose email is already used by any other owner, compared on the
543	     * lower-cased form so addresses that differ only in letter case still collide. The incoming
544	     * value has already been trimmed and lower-cased by {@link #normalizeEmail}; each existing
545	     * owner's stored email is lower-cased the same way before comparison. Owners without an email
546	     * are ignored, and a request that supplies no email is never rejected. A match results in a
547	     * 409 response naming {@code email}.
548	     */
549	    private void rejectDuplicateEmail(OwnerFieldsDto ownerFieldsDto) {
550	        String email = ownerFieldsDto.getEmail();
551	        if (email == null) {
552	            return;
553	        }
554	        for (Owner existing : this.clinicService.findAllOwners()) {
555	            String existingEmail = existing.getEmail();
556	            if (existingEmail != null && email.equals(existingEmail.toLowerCase(Locale.ROOT))) {
557	                throw new DuplicateOwnerEmailException(email);
558	            }
559	        }
560	    }
561	
562	    /**
563	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
564	     * day. When the caller supplies no value it defaults to the server's current date; a value
565	     * provided in the request is kept. The effective date, whether supplied or defaulted, must fall
566	     * on a business day: a Saturday or Sunday is rolled forward to the following Monday. The adjusted
567	     * date is written back onto the request so it is what gets stored and returned (in ISO
568	     * {@code YYYY-MM-DD} format) and what every value derived from the registration date is based on.
569	     */
570	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
571	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
572	        if (effective == null) {
573	            effective = LocalDate.now();
574	        }
575	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
576	    }
577	
578	    /**
579	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
580	     * Monday; a weekday is returned unchanged.
581	     */
582	    private static LocalDate toBusinessDay(LocalDate date) {
583	        return switch (date.getDayOfWeek()) {
584	            case SATURDAY -> date.plusDays(2);
585	            case SUNDAY -> date.plusDays(1);
586	            default -> date;
587	        };
588	    }
589	
590	    /**
591	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
592	     * where {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} is the
593	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a per-city 4-digit
594	     * zero-padded sequence equal to one more than the number of owners already in that city
595	     * (e.g. {@code 'SYD-SMI-0007'}).
596	     */
597	    private void assignCustomerCode(Owner owner) {
598	        String city = owner.getCity();
599	        String lastName = owner.getLastName();
600	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
601	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
602	        int sequence = 1;
603	        for (Owner existing : this.clinicService.findAllOwners()) {
604	            if (city.equalsIgnoreCase(existing.getCity())) {
605	                sequence++;
606	            }
607	        }
608	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
609	    }
610	
611	    /**
612	     * Assigns the owner's {@code membershipNumber} on create, formatted
613	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
614	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}). Assigned after
615	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
616	     * inputs are present.
617	     */
618	    private void assignMembershipNumber(Owner owner) {
619	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
620	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
621	    }
622	
623	    /**
624	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
625	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
626	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
627	     */
628	    private void assignNamesakeCount(Owner owner) {
629	        String firstName = owner.getFirstName();
630	        String lastName = owner.getLastName();
631	        int count = 0;
632	        for (Owner existing : this.clinicService.findAllOwners()) {
633	            if (firstName.equalsIgnoreCase(existing.getFirstName())
634	                && lastName.equalsIgnoreCase(existing.getLastName())) {
635	                count++;
636	            }
637	        }
638	        owner.setNamesakeCount(count);
639	    }
640	
641	    /**
642	     * Assigns the new owner's {@code membershipLevel} on create: a number from 1 to 3 starting at
643	     * 1, plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3.
644	     * Level 4 is reserved for tenure. Runs after {@link #assignNamesakeCount} so that count is
645	     * settled.
646	     */
647	    private void assignMembershipLevel(Owner owner) {
648	        int level = 1;
649	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
650	            level++;
651	        }
652	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
653	            level++;
654	        }
655	        owner.setMembershipLevel(Math.min(level, 3));
656	    }
657	
658	    /**
659	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
660	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
661	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
662	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
663	     * pre-existing owners for that day.
664	     */
665	    private void assignBulkSignupWarning(Owner owner) {
666	        LocalDate registrationDate = owner.getRegistrationDate();
667	        int count = 0;
668	        for (Owner existing : this.clinicService.findAllOwners()) {
669	            if (registrationDate.equals(existing.getRegistrationDate())) {
670	                count++;
671	            }
672	        }
673	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
674	    }
675	
676	    /**
677	     * Assigns the new owner's {@code householdId} when the request opts in with
678	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
679	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
680	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
681	     * all end up carrying one stable shared identifier: if any existing member already has a
682	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
683	     * and address. Any existing member that is missing the identifier is updated so the whole
684	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
685	     * identifier is assigned.
686	     */
687	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
688	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
689	            return;
690	        }
691	        String lastName = normalizeForComparison(owner.getLastName());
692	        String address = canonicalAddress(owner.getAddress());
693	        List<Owner> members = new ArrayList<>();
694	        for (Owner existing : this.clinicService.findAllOwners()) {
695	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
696	                && address.equals(canonicalAddress(existing.getAddress()))) {
697	                members.add(existing);
698	            }
699	        }
700	        if (members.isEmpty()) {
701	            return;
702	        }
703	        String householdId = members.stream()
704	            .map(Owner::getHouseholdId)
705	            .filter(id -> id != null && !id.isBlank())
706	            .findFirst()
707	            .orElseGet(() -> newHouseholdId(lastName, address));
708	        owner.setHouseholdId(householdId);
709	        for (Owner member : members) {
710	            if (!householdId.equals(member.getHouseholdId())) {
711	                member.setHouseholdId(householdId);
712	                this.clinicService.saveOwner(member);
713	            }
714	        }
715	    }
716	
717	    /**
718	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
719	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
720	     * every existing owner already carrying the same identifier. Runs after {@link #assignHousehold}
721	     * so the identifier is settled. Left {@code null} when the owner belongs to no household.
722	     */
723	    private void assignHouseholdMembership(Owner owner) {
724	        String householdId = owner.getHouseholdId();
725	        if (householdId == null || householdId.isBlank()) {
726	            owner.setHouseholdMemberCount(null);
727	            return;
728	        }
729	        int count = 1;
730	        for (Owner existing : this.clinicService.findAllOwners()) {
731	            if (householdId.equals(existing.getHouseholdId())) {
732	                count++;
733	            }
734	        }
735	        owner.setHouseholdMemberCount(count);
736	    }
737	
738	    /**
739	     * Derives a stable household identifier from the normalized last name and address: the first
740	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
741	     * owners in the same household therefore derive the same value regardless of creation order.
742	     */
743	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
744	        try {
745	            byte[] digest = MessageDigest.getInstance("SHA-256")
746	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
747	            StringBuilder hex = new StringBuilder(digest.length * 2);
748	            for (byte b : digest) {
749	                hex.append(String.format("%02x", b));
750	            }
751	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
752	        } catch (NoSuchAlgorithmException ex) {
753	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
754	        }
755	    }
756	}
